import math
from scipy.integrate import dblquad


def cross(a, b):
    return (a[1]*b[2] - a[2]*b[1],
            a[2]*b[0] - a[0]*b[2],
            a[0]*b[1] - a[1]*b[0])


def flux(F, r, r_u, r_v, u0, u1, v0, v1):
    def g(v, u):
        f = F(r(u, v))
        n = cross(r_u(u, v), r_v(u, v))
        return f[0]*n[0] + f[1]*n[1] + f[2]*n[2]
    return dblquad(g, u0, u1, lambda u: v0, lambda u: v1)[0]

