import math
def _sph(u, v):
    return (math.sin(u)*math.cos(v), math.sin(u)*math.sin(v), math.cos(u))
def _sph_u(u, v):
    return (math.cos(u)*math.cos(v), math.cos(u)*math.sin(v), -math.sin(u))
def _sph_v(u, v):
    return (-math.sin(u)*math.sin(v), math.sin(u)*math.cos(v), 0.0)
SPHERE = (_sph, _sph_u, _sph_v)
SPHERE_SWAPPED = (lambda u, v: _sph(v, u), lambda u, v: _sph_v(v, u), lambda u, v: _sph_u(v, u))
PARABOLOID = (lambda u, v: (u*math.cos(v), u*math.sin(v), 1 - u*u),
              lambda u, v: (math.cos(v), math.sin(v), -2*u),
              lambda u, v: (-u*math.sin(v), u*math.cos(v), 0.0))
ROOF = (lambda u, v: (u, v, u), lambda u, v: (1.0, 0.0, 1.0), lambda u, v: (0.0, 1.0, 0.0))
